1382: \begin{lemma}\label{lem:3-mom}
1383: Let $T,R>0$, and suppose
1384: \[
1385:  f(t,x,p)  =e^{-t}f_0(x-tp,p) +\int_0^te^{-(t-s)}G(s,x-(t-s)p,p)\,\ds,
1386: \]
1387: where $f_0,G\geq0$.  Then
1388: \begin{align*}
1389:  &\int_0^T\int_{B_R}\int_{\R^3}|p|^3f(t,x,p)\,\dpp\dx\dt \\
1390:  &\quad\leq 2R\lt(  \iint_{\R^3\times\R^3}|p|^2f_0(x,p)\,\dx\dpp  +\int_0^T\iint_{\R^3\times\R^3}|p|^2G(s,x,p)\,\dx\dpp\ds  \rt).
1391: \end{align*}
1392: \end{lemma}

432: \begin{lemma}[Characteristic reparametrization]\label{lem:twist}
433: Let $0<T\leq1$.  There exists $\delta_0=\delta_0(d)>0$ such that, if
434: \begin{equation}\label{small-field}
435:  \int_0^T\norm{E(s)}_{C^{1,\alpha}}\dd s\leq\delta_0,
436: \end{equation}
437: then for every $0\leq s<t\leq T$, there is a global $C^1$ map
438: $\Psi_{s,t}:\R^d_x\times\R^d_v\to\R^d_v$ satisfying
439: \begin{equation}\label{Psi-definition}
440:  X_{s,t}\bigl(x,\Psi_{s,t}(x,v)\bigr)=x-(t-s)v.
441: \end{equation}
442: For $t>0$ and $x,y\in\R^d$, set
443: \begin{equation}\label{VWJ-definition}
444:  \mathcal V_t(x,y)
445:  :=\Psi_{0,t}\left(x,\frac{x-y}{t}\right),\qquad
446:  \mathcal W_t(x,y)
447:  :=V_{0,t}\bigl(x,\mathcal V_t(x,y)\bigr),
448: \end{equation}
449: and
450: \begin{equation}\label{J-definition}
451:  J_t(x,y)
452:  :=\left|\det D_v\Psi_{0,t}
453:        \left(x,\frac{x-y}{t}\right)\right|.
454: \end{equation}
455: Then
456: \begin{equation}\label{endpoint-identities}
457:  X_{0,t}\bigl(x,\mathcal V_t(x,y)\bigr)=y,\qquad
458:  V_{0,t}\bigl(x,\mathcal V_t(x,y)\bigr)=\mathcal W_t(x,y),
459: \end{equation}
460: the map $v\mapsto X_{0,t}(x,v)$ is a global $C^1$ diffeomorphism, and
461:  \begin{align}
462:  \left|\mathcal V_t(x,y)-\frac{x-y}{t}\right|
463:  +\left|\mathcal W_t(x,y)-\frac{x-y}{t}\right|
464:  &\leq C\int_0^t\norm{E(\tau)}_{L^\infty}\dd\tau,\label{VWfree}\\
465:  C^{-1}\leq J_t(x,y)&\leq C,\label{twistbounds}\\
466:  \left|\mathcal W_t(x,y)-\mathcal W_t(x',y)\right|
467:  &\leq C\frac{|x-x'|}{t},\label{W-Lipschitz}\\
468:  |J_t(x,y)-J_t(x',y)|
469:  &\leq C|x-x'|^\alpha
470:        \int_0^t\norm{E(\tau)}_{C^{1,\alpha}}\dd\tau.\label{Jholder}
471: \end{align} 
472: All constants are uniform under \eqref{small-field}.
473: \end{lemma}

515: 	{\begin{lemma} \label{lem:averaging-localized-integrated}
516: 		Let $T>0$ and $h \in L^{\infty}([-T,T]; L^2_{x,v}(\bbR^n\times\bbR^n)), g = ( g_{i} )_{i=1}^{n} \in L^2_{t, x, v}([-T, T]\times\mathbb{R}^n\times\mathbb{R}^n)$  satisfy
517: 		$$\partial_t h + v\cdot \nabla_x h=  \nb_{v} \cdot g$$ on $[-T, T]$ in the sense of distributions. Assume further that there exists some $Q>0$ such that $$h(t, x, v)=0$$ for $\vert v\vert>Q$, $t\in [-T, T]$ and $x\in \mathbb{R}^n$. Then, for any $a \in (0,1/4]$, $\rho_{h}(t, x):=\int_{\bbR^{n}} h(t, x, v)dv$ satisfies
518: 		\begin{flalign*}
519: 			\int_{-T}^{T} \nrm{\rho_{h}(t,\cdot)}^{1+4a}_{H^{\frac14 - a }(\bbR^n)}  dt & \le C (1+Q)^{\frac{(1+4a)n}{2}} T^{16a^2}\left( (1+T^2)^\frac{1+4a}{2}\Vert h\Vert_{L^\infty([-T,T]; L^{2})}^{1+4a} + T^\frac{1+4a}{2} \Vert g \Vert_{L^2}^{1+4a} \right)
520: 		\end{flalign*}  with $C>0$ independent of $Q, T$. 
521: 	\end{lemma}

