363: \begin{lemma}
364:     The solutions $\psi^{(k)}(t) = \sum_{i,j=1}^r X_i^{(k)}(t) S_{ij}^{(k)}(t) W_j^{(k)}(t)$ for $k=1,2,3$ are determined as follows:
365:     \begin{enumerate}
366:         \item \textbf{K-step}: $W_j^{(1)}$ remains constant ($W_j^{(1)}(t) = W_j(t_n)$). The updated spatial factors $K_j(t, x) = \sum_{i=1}^r X_i^{(1)}(t) S_{ij}^{(1)}(t)$ evolve according to:
367:         \begin{align*}
368:             \partial_t K_j(t, x) = \langle F(t, \sum_{j=1}^r K_j(t, x) W_j(t_n, \xi)), W_j(t_n, \xi) \rangle_{\xi}, \quad j=1,\dots,r.
369:         \end{align*}
370:         \item \textbf{S-step}: Both $X_i^{(2)}$ and $W_j^{(2)}$ remain constant ($X_i^{(2)} = X_i^{(1)}(t_{n+1}), W_j^{(2)} = W_j(t_n)$). The core matrix $S_{ij}^{(2)}$ evolves according to:
371:         \begin{align*}
372:             \partial_t S_{ij}^{(2)} = -\langle F(t, \sum_{k,l=1}^r X_k^{(2)} S_{kl}^{(2)} W_l^{(2)}), X_i^{(2)} W_j^{(2)} \rangle_{x,\xi}, \quad i,j=1,\dots,r.
373:         \end{align*}
374:         \item \textbf{L-step}: $X_i^{(3)}$ remains constant ($X_i^{(3)} = X_i^{(1)}(t_{n+1})$). The updated random factors $L_i(t, \xi) = \sum_{j=1}^r S_{ij}^{(3)}(t) W_j^{(3)}(t)$ evolve according to:
375:         \begin{align*}
376:             \partial_t L_i(t, \xi) = \langle F(t, \sum_{i=1}^r X_i^{(3)}(x) L_i(t, \xi)), X_i^{(3)}(x) \rangle_{x}, \quad j=1,\dots,r.
377:         \end{align*}
378:     \end{enumerate}
379: \end{lemma}

1508: 	\begin{lem}
1509: 		Let $\delta\in\R$, $\sigma\in\R_+^3$, and $p\geq 1$. Then there exists $C>0$, independent of $\delta, \sigma$, and $p$, such that 
1510: 		\begin{multline*}
1511: 			\Sigma:=\sum_{n\in\N_0^3:\, \sigma\cdot n \geq \delta} e^{-\sigma\cdot n +\delta}\, n_j^\frac{p}{2} \le \lt(\frac{p}{e}\rt)^{\frac{p}{2}}\frac{e^\delta}{\sigma_j^{p/2}} \prod^3_{i=1} \frac{\weight{\sigma_i}}{\sigma_i}\indic_{\{\delta< 0\}}
1512:             \\
1513:             + \frac{C}{\sigma_j^{p/2}}
1514: 			\lt(\lt( p^\frac{p}{2} + \lt(2\delta\rt)^\frac{p}{2} \rt)
1515: 			+ \lt(1+\frac{\delta}{\weight{\sigma_{j+1}}}\rt) \frac{\delta^{\frac{p}{2}+1}}{\weight{\sigma_j}} \rt) \prod_{k=1}^3 \frac{\weight{\sigma_k}}{\sigma_k}\indic_{\{\delta\ge 0\}}\,,
1516: 		\end{multline*}
1517: 		where $j+1$ can be replaced by $j+2$ and is modulo $3$.
1518: 	\end{lem}

355: \begin{theorem}[Nonlinear phase mixing]\label{maintheorem}
356: Fix dimension $d\geq3$ and $M:=\ceils{(d+1)/2}$. Choose constants $N_0>\sigma_1>\sigma_0$ satisfying \[\sigma_1\geq d+8,\quad N_0-\sigma_1>3d/2+7/2 \qaq \sigma_1-\sigma_0>d+1.\] Let $g\in H^{N_0+7/2+\delta_0}_{2+\ceils{d/2}}(\R^d;\R_+)$ for some constant $\delta_0\in(0,1]$, and let $w\in L^1(\R^d,\R)$ satisfy
357: \begin{align}
358: \abs{\widehat w(k)}\lesssim\frac{1}{\jb{k}^{M-1/2}}\label{wassumption}
359: \end{align}for all $k\in\R^d$. Assume $g$ and $w$ satisfy the uniform Penrose condition \eqref{Penrose} with constant ${c_{\mathrm{P}}}$. Then there exist constants $C>0$ and $\ep_0>0$, depending only on $N_0,\sigma_1,\sigma_0,w,g,{c_{\mathrm{P}}},d,\delta_0$, and independent of $\hbar\in(0,1]$, such that the following holds.
360: 
361: For any $\ep\in(0,\ep_0]$ and any self-adjoint initial data $\Qin\in\mathcal{H}^{N_0}_{M,M}$ with \[\norm{\Qin}_{\mathcal{H}^{N_0}_{M,M}}\leq\ep,\]
362: the nonlinear Hartree equation \eqref{NH} admits a unique global self-adjoint solution $Q(t)$, which satisfies:
363: \begin{itemize}
364: \item Density decay: for all $k\in\R^d$ and $t\geq 0$,\begin{align}
365: \label{T1}\abs{\widehat{\rho_Q}(t,k)}&\leq \frac{C\ep}{\jb{k, kt}^{\sigma_1}}.
366: \end{align}
367: \item Scattering: there exists an operator $Q_\infty\in\mathcal H^{\sigma_0}_M(\R^d;\C)$ such that, for all $t\geq 0$,
368: \begin{align}
369: \label{T2}
370: \norm{e^{-i\Psfrac{\hbar}{2}t\Delta}Q(t)e^{i\Psfrac{\hbar}{2}t\Delta}-Q_\infty}_{\mathcal H^{\sigma_0}_{M}}&\leq \frac{C\ep}{\jb{t}^{d/2}}.
371: \end{align}
372: \end{itemize}
373: \end{theorem}

