241: \begin{theo} \label{main}
242: Let $w$ be a given finite signed Borel measure on $\BR^3$. Let $f \in L^1_\xi \cap L^\I_\xi$ satisfy $\|\lxr^2 f\|_{L^1_\xi \cap L^\I_\xi} < \I$. Assume that the operator $\CL_1 = \CL_1(f,w)$ satisfies
243: \begin{align}
244: \left\|(1+\CL_1)^{-1}\right\|_{\CB(L^2_{t,x})} < \I.
245: \end{align}
246: Then there exists $\ep_0 > 0$ such that the following holds. If $\| Q_0 \|_{\CH^{1/2,3/2}} \leq \ep_0$, then there exists a unique global solution $Q(t) \in C(\BR, \CH^\tw)$ to~\eqref{$f$-NLH} with $Q(0)=Q_0$ such that $\rh_Q \in L^2_t(\BR, H^\tw_x)$. Furthermore, $Q(t)$ scatters; that is, there exist $Q_{\pm} \in \FS^3$ such that
247: \begin{align}
248: U(-t)Q(t)U(t) \to Q_\pm \text{ in } \FS^3 \text{ as } t \to \pm \I.
249: \end{align}
250: \end{theo}

474: \begin{lemma}\label{L2normofWigner}
475: Suppose $Q\in\mathcal L^2(\R^d;\C)$. Then the Wigner transform of $Q$ satisfies
476: \begin{align*}
477: \norm{W[Q](x,\xi)}_{L^2_{x,\xi}}=(2\pi\hbar)^{-d/2}\norm{Q(x,y)}_{L^2_{x,y}}=\norm{Q}_{\mathcal L^2}.
478: \end{align*}
479: \end{lemma}

1362: \begin{proposition}[Linearised phase mixing]
1363: Let $N_0,N_1\geq0$ be constants such that $0\leq N_1<N_0-d/2-1$. Assume $w\in L^1(\R^d)$ and $g\in H^{N_0+9/2+\delta_0}_{2+\ceils{d/2}}(\R^d)$, for some $0<\delta_0\ll 1$, satisfy the uniform Penrose condition \eqref{Penrose} with constant ${c_{\mathrm{P}}}$. Assume the initial perturbation satisfies \[\norm{\Qin}_{\mathcal H^{N_0+1}_{M,M}}<\infty.\] Then, there exists a constant $C=C(N_0,w,g,{c_{\mathrm{P}}},d,\delta_0)$, independent of $\hbar\in (0,1]$, such that the solution ${Q_{\mathrm{L}}}$ to the linearised Hartree equation \eqref{LH} with initial data ${Q_{\mathrm{L}}}(0)=\Qin$ satisfies the following.
1364: \begin{itemize}
1365: \item Density decay: for all $k\in\R^d$ and $t\geq0$,
1366: \begin{align*}
1367: \jb{k, kt}^{N_0}\abs{\widehat{\rho_{Q_{\mathrm{L}}}}(t,k)}\leq C\norm{Q_{\mathrm{in}}}_{\mathcal H^{N_0+1}_{M,M}}.
1368: \end{align*}
1369: \item Scattering: there exists an operator $Q_\infty\in \mathcal H^{N_1}(\R^d;\C)$ such that, for $t\geq 0$ and $\hbar\in (0,1]$,\vspace*{-3pt}
1370: \begin{align}\label{scatteringstatement}
1371: \Bnorm{\jb{t\bm{\nabla}_{x}, \bm{\nabla}_\xi}^{N_1}\sbbr{e^{-i\Psfrac{\hbar}{2}t\Delta}{Q_{\mathrm{L}}}(t)e^{i\Psfrac{\hbar}{2}t\Delta}-Q_\infty}}_{\mathcal L^2}\leq C\frac{\norm{Q_{\mathrm{in}}}_{\mathcal H^{N_0+1}_{M,M}}}{\jb{t}^{d/2}}.
1372: \end{align}
1373: \end{itemize}
1374: \end{proposition}\begin{remark}

